import{r as e,u as t}from"./index-DP1lPwSp.js";var n=t(),r=[{title:`1. Bookings`,body:[`An appointment is held for you from the moment you confirm it on this website. Bookings are for the named service, barber, date and time shown in your confirmation.`,`If your chosen barber becomes unavailable through illness or emergency, we will contact you to offer the same service with another barber or a new time.`]},{title:`2. Cancellations and changes`,body:[`Please give at least 12 hours' notice to cancel or move an appointment. Call us on `+e.phone+` or email `+e.email+`.`,`Repeated no-shows may mean we ask for a deposit before future bookings.`]},{title:`3. Lateness`,body:[`We hold your chair for 10 minutes. After that we may need to shorten the service so the next guest is not delayed, or move you to the next available slot.`]},{title:`4. Prices and payment`,body:[`Prices listed on the Services page are in pounds sterling and include VAT. We accept card and cash in the shop; no payment is taken online.`,`Prices may change, but the price shown when you book is the price you pay for that appointment.`]},{title:`5. Children and under-18s`,body:[`Guests under 16 must be accompanied by a parent or guardian, who remains in the shop for the duration of the service.`]},{title:`6. Health, skin and allergies`,body:[`Tell your barber before the service about skin conditions, allergies or recent treatments. Straight-razor shaves are not carried out on broken or inflamed skin.`,`We are not able to provide medical advice, and services are refused where we believe they would harm your skin.`]},{title:`7. Satisfaction`,body:[`If you are unhappy with your cut, tell us within 7 days and we will put it right free of charge with the same barber where possible. We do not offer cash refunds on completed services.`]},{title:`8. Your information`,body:[`The name, email and phone number you give at booking are used only to manage your appointment and contact you about it. We do not sell your details or add you to marketing lists without your consent.`,`Calendar events you generate are created in your own device or account; we have no access to your calendar.`]},{title:`9. Conduct and property`,body:[`We ask everyone in the shop to be courteous to our team and other guests. We may decline service to anyone behaving abusively or arriving intoxicated.`,`Please look after your belongings; we cannot accept responsibility for items left in the shop.`]},{title:`10. Contact`,body:[e.name+`, `+e.address+`. Telephone `+e.phone+`. Email `+e.email+`.`,`These terms are governed by the law of England and Wales.`]}];function i(){return(0,n.jsx)(`section`,{children:(0,n.jsxs)(`div`,{className:`mx-auto max-w-3xl px-6 lg:px-10 py-20 lg:py-28`,children:[(0,n.jsx)(`p`,{className:`text-xs font-medium uppercase tracking-[0.35em] text-brass`,children:`Legal`}),(0,n.jsx)(`h1`,{className:`mt-4 font-serif font-medium text-5xl leading-tight text-balance`,children:`Terms & Conditions`}),(0,n.jsx)(`p`,{className:`mt-5 text-sm text-cream/50`,children:`Last updated 1 September 2026.`}),(0,n.jsx)(`div`,{className:`mt-12 space-y-10`,children:r.map(e=>(0,n.jsxs)(`div`,{children:[(0,n.jsx)(`h2`,{className:`font-serif text-2xl text-cream`,children:e.title}),e.body.map(e=>(0,n.jsx)(`p`,{className:`mt-3 text-sm text-cream/70 leading-relaxed text-pretty`,children:e},e))]},e.title))})]})})}export{i as component};